SELECT base_colour, catalog_rows, distinct_products, ROUND(100.0 * catalog_rows / SUM(catalog_rows) OVER (), 2) AS pct_of_catalog, ROUND(100.0 * SUM(catalog_rows) OVER (ORDER BY catalog_rows DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) / SUM(catalog_rows) OVER (), 2) AS cumulative_pct FROM (SELECT COALESCE(base_colour, 'Unknown') AS base_colour, COUNT(*) AS catalog_rows, COUNT(DISTINCT product_id) AS distinct_products FROM fashion.catalog.products GROUP BY base_colour) t ORDER BY catalog_rows DESC LIMIT 15
